{page==='Super Admin'&&owner&&<section className="panel backup-panel admin-customers"><h2>Customers</h2><p>Paid status is entered manually after you verify payment. Overdue does not automatically suspend anyone.</p><p>Database storage: {adminData?.storage?((adminData.storage.usedBytes/1e6).toFixed(1)+' MB / 500 MB (approximate)'):'Loading'} {adminData?.storage?.usedBytes>400_000_000&&<strong className="error">Near free storage cap; review capacity before adding customers.</strong>}</p><div className="table-wrap"><table><thead><tr><th>Customer</th><th>Joined</th><th>Paid through</th><th>State</th><th>Sheet backup</th><th>Actions</th></tr></thead><tbody>{(adminData?.customers||[]).filter((c:Rec)=>c.sub!==adminData?.ownerSub&&!c.deleted_at).map((c:Rec)=><tr key={c.sub}><td data-label="Customer"><b>{c.name}</b><small className="subtext">{c.email}</small></td><td data-label="Joined">{date(c.created_at)}</td><td data-label="Paid through">{date(c.paid_through)||'Trial'}</td><td data-label="State">{c.suspended?'Suspended':c.billing?.overdue?'Overdue':'Active'}</td><td data-label="Sheet backup">{c.mirror_error||'OK'}</td><td data-label="Actions" className="actions"><button disabled={!!c.deleted_at} onClick={()=>{setPaymentTarget(c);setAdminPaymentMode('');setAdminPaymentNote('');setAdminPaymentKey(crypto.randomUUID());setError('')}}>Record manual payment</button><button disabled={!!c.deleted_at} onClick={()=>adminAction(c.sub,c.suspended?'restore':'suspend')}>{c.suspended?'Restore':'Suspend'}</button><button className="delete-customer-button" onClick={()=>openCustomerDelete(c)}>Delete</button></td></tr>)}</tbody></table></div></section>}
