{page==='Super Admin'&&owner&&<section className="panel backup-panel admin-customers"><h2>Deleted accounts</h2><p>Access is blocked. Restore within 48 hours of deletion, or delete permanently now. Due accounts are purged by the cleanup process; if Google deletion fails, the account remains here for retry, without access.</p><div className="table-wrap"><table><thead><tr><th>Customer</th><th>Deleted</th><th>Time remaining</th><th>Cleanup status</th><th>Actions</th></tr></thead><tbody>{(adminData?.customers||[]).filter((c:Rec)=>c.deleted_at).map((c:Rec)=><tr key={c.sub}><td data-label="Customer"><b>{c.name}</b><small className="subtext">{c.email}</small></td><td data-label="Deleted">{new Date(c.deleted_at).toLocaleString('en-IN')}</td><td data-label="Time remaining">{Math.max(0,Math.ceil((new Date(c.deleted_at).getTime()+48*60*60*1000-Date.now())/3600000))} hours (until {new Date(new Date(c.deleted_at).getTime()+48*60*60*1000).toLocaleString('en-IN')})</td><td data-label="Cleanup status">{c.sheet_deleted_at?'Sheet removed; finishing database deletion':c.purge_error?'Needs review: '+c.purge_error:c.purge_started_at?'Removal in progress':new Date(c.deleted_at).getTime()+48*60*60*1000<=Date.now()?'Due for cleanup':'Pending'}</td><td data-label="Actions" className="actions"><button disabled={!!c.purge_started_at||!!c.sheet_delete_attempted_at||!!c.sheet_deleted_at||Date.now()>=new Date(c.deleted_at).getTime()+48*60*60*1000} onClick={()=>restoreCustomer(c)}>Restore</button><button className="danger-button" disabled={!!c.purge_started_at&&new Date(c.purge_started_at).getTime()>Date.now()-15*60*1000} onClick={()=>permanentlyDeleteCustomer(c)}>Delete permanently now</button></td></tr>)}</tbody></table></div></section>}
